// A type guard to check if a key is a valid Lucide icon name
export function isValidIcon(key: string | undefined): key is keyof typeof LucideIcons {
  if (!key) return false;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return key in (LucideIcons as any);
}

export const getIcon = (name: string | undefined): LucideIcon => {
    if (isValidIcon(name)) {
        return LucideIcons[name];
    }
    return Component;
}


export type Panel = {
  id: string;
  title: string;
  type: 'editor' | 'media' | 'sound' | '3d' | 'layout';
  editorType?: 'default' | 'fountain' | 'prose';
  content: string; // For editor, filename for others, or JSON string for layout
  purpose:string; // For AI prompt
  imageId?: string; // For media panels
  icon?: string;
  layoutGrid?: [number, number]; // For layout panels e.g., [2, 2] for a 4-panel grid
};

export type Tab = {
  id: string;
  name: string;
  panels: Panel[];
  icon?: string;
};

export type Tool = {
  id: string;
  name: string;
  icon: string;
  layout: Tab[];
};

